implicit def catsDataRepresentableForPair(implicit
  PF: Functor[λ[P => (P, P)]]
): Representable.Aux[λ[P => (P, P)], Boolean] =
  new Representable[λ[P => (P, P)]] {
    override type Representation = Boolean
    override val F: Functor[λ[P => (P, P)]] = PF

