void reference_merge_patch(json& target, const json& patch)
{
    if (!patch.is_object())
    {
        target = patch;
        return;
    }
    if (!target.is_object())
    {
        target = json::object();
    }
    for (auto it = patch.begin(); it != patch.end(); ++it)
    {
        if (it.value().is_null())
        {
            target.erase(it.key());
        }
        else
        {
            reference_merge_patch(target[it.key()], it.value());
        }
    }
}
