      })

      // Mark all as processed
      processed.add(issue.number)
      duplicates.forEach((d) => processed.add(d.issue2))
    }
  }

  return duplicateGroups.sort(
    (a, b) => b.duplicates.length - a.duplicates.length,
  )
}
