export function extractErrorMessage(body: string): string | null {
  const patterns = [
    /Error: (.+?)(?:\n|$)/i,
    /TypeError: (.+?)(?:\n|$)/i,
    /Exception: (.+?)(?:\n|$)/i,
    /Failed to (.+?)(?:\n|$)/i,
  ]

  for (const pattern of patterns) {
    const match = body.match(pattern)
    if (match) return match[1].trim()
  }

  return null
}
