/** Get cached `findNearestPackageData` value based on `basedir`. When one is found, and we've already traversed some directories between `basedir` and `originalBasedir`, we cache the value for those in-between directories as well. This makes it so the fs is only read once for a shared `basedir`. */
function getFnpdCache(
  packageCache: PackageCache,
  basedir: string,
  originalBasedir: string,
) {
  const cacheKey = getFnpdCacheKey(basedir)
  const pkgData = packageCache.get(cacheKey)
  if (pkgData) {
    traverseBetweenDirs(originalBasedir, basedir, (dir) => {
      packageCache.set(getFnpdCacheKey(dir), pkgData)
    })
    return pkgData
  }
