  if (_terminated) {
    throw StateError('This pool has already been terminated.');
  }

  while (true) {
    final pooled = _select();
    pooled.inFlightCount++;
    final PoolLease lease;
    try {
      lease = PoolLease._(
        this,
        pooled,
        pooled.value ??= await pooled.creation,
      );
