        ProtoWithAnnotationsAndJsonNames.newBuilder().setJsonNameOnly("zzz").build();
    String jsonWithoutJsonName = "{\"jsonNameOnly\":\"zzz\"}";
    String jsonWithJsonName = "{\"aaa\":\"zzz\"}";

