```typescript
/** Generates a race between the promise(s) and the AbortSignal This avoids `Promise.race()`-related memory leaks: https://github.com/nodejs/node/issues/17469#issuecomment-349794909 */
export function raceWithSignal<T>(
  signal: AbortSignal,
  promise: Promise<T>,
): Promise<T> {
  let cleanup = noop
  return new Promise<T>((resolve, reject) => {
    const notifyRejection = () => reject(new TaskAbortError(signal.reason))

    if (signal.aborted) {
      notifyRejection()
      return
    }

    cleanup = addAbortSignalListener(signal, notifyRejection)
    promise.finally(() => cleanup()).then(resolve, reject)
  }).finally(() => {
    // after this point, replace `cleanup` with a noop, so there is no reference to `signal` any more
    cleanup = noop
  })
}
