/** Remove duplicates. Duplicates are checked using `Order[_]` instance. Example: {{{ scala> import cats.data.Chain scala> val chain = Chain(1, 2, 2, 3) scala> chain.distinct res0: cats.data.Chain[Int] = Chain(1, 2, 3) }}} */
def distinct[AA >: A](implicit O: Order[AA]): Chain[AA] = {
  if (isEmptyOrSingleton) this
  else {
    implicit val ord: Ordering[AA] = O.toOrdering

    val bldr = Vector.newBuilder[AA]
    val seen = mutable.TreeSet.empty[AA]
    val it = iterator
    while (it.hasNext) {
      val next = it.next()
      if (seen.add(next))
        bldr += next
    }
    // Result can contain a single element only.
    Chain.fromSeq(bldr.result())
  }
}
