/// <summary>A left-associative variant of 'FoldMap' that is strict in the accumulator. Use this method for strict reduction when partial results are merged via `Append`.</summary>
public static virtual B FoldMapUntilBack<A, B>(Func<A, B> f, Func<(B State, A Value), bool> predicate, K<T, A> ta)
    where B : Monoid<B>
{
    var step = T.FoldStepBack(ta, B.Empty);
    while(true)
    {
        switch (step)
        {
            case Fold<A, B>.Done(var state):
                return state;

            case Fold<A, B>.Loop(var state, var value, var next):
                if (predicate((state, value)))
                {
                    return state;
                }
                else
                {
                    step = next(state + f(value));
                }
                break;

            default: 
                throw new NotSupportedException();
        }
    }
}
