  if (options.secure) {
    header += '; Secure';
  }
  if (options.partitioned) {
    if (!options.secure) {
      throw new TypeError(
        `Invalid options for cookie "${name}": "partitioned" requires "secure: true"`,
      );
    }
    header += '; Partitioned';
  }
  if (options.priority !== undefined) {
    const priority = PRIORITY_VALUES.get(
