  schemas?: Record<string, SchemaObject>,
): void {
  if (descs.self) {
    schema.description = descs.self;
  }

  for (const [propPath, description] of descs.properties) {
    setNestedDescription({
      schema,
      pathParts: propPath.split('.'),
      description,
      schemas,
    });
  }
}
