```typescript
/** A count bound reaches generated source verbatim, so a non-number would be emitted as code rather than as a value — `min('0) {} evil(); if (0')` writes an arbitrary statement into the function body. TypeScript types these as `number` and fromJSONSchema guards them, so this is a backstop rather than a live hole, but generated source is the one place a wrong type stops being a type error. */
function numericOperand(value: unknown, label: string): string {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new ZodCompileUnsupportedError(`${label} bound of type ${typeof value}`);
  }
  return `${value}`;
}
