  issue1: CategorizedIssue,
  issue2: CategorizedIssue,
): SimilarityResult {
  const signals: SimilaritySignals = {
    titleSimilarity: calculateTitleSimilarity(issue1.title, issue2.title),
    keywordOverlap: calculateKeywordOverlap(issue1, issue2),
