	// Start displaying the progress bar.
	progressBar.tick(0, { elapsedErrors: 0 });

	const crashTestResults = fuzz({
		linter,
		count: crashTestCount,
		checkAutofixes: false,
		progressCallback(elapsedErrors) {
			progressBar.tick(1, { elapsedErrors });
			progressBar.render();
