	const autofixTestResults = fuzz({
		linter,
		count: autofixTestCount,
		checkAutofixes: true,
		progressCallback(elapsedErrors) {
			progressBar.tick(ESTIMATED_CRASH_AUTOFIX_PERFORMANCE_RATIO, {
				elapsedErrors: crashTestResults.length + elapsedErrors,
