```c
static int uv__fs_read(uv_fs_t* req) {
  const struct iovec* bufs;
  unsigned int iovmax;
  size_t nbufs;
  ssize_t r;
  off_t off;
  int fd;

  fd = req->file;
  off = req->off;
  bufs = (const struct iovec*) req->bufs;
  nbufs = req->nbufs;

  iovmax = uv__getiovmax();
  if (nbufs > iovmax)
    nbufs = iovmax;

  /* Truncate multi-buf reads to UV__IO_MAX_BYTES total, dropping trailing bufs. */
  if (nbufs > 1) {
    size_t total;
    size_t n;
    for (total = 0, n = 0; n < nbufs; n++) {
      if (bufs[n].iov_len > UV__IO_MAX_BYTES - total)
        break;
      total += bufs[n].iov_len;
    }
    nbufs = n > 0 ? n : 1;
  }

  r = 0;
  if (off < 0) {
    if (nbufs == 1) {
      r = read(fd, bufs->iov_base,
               bufs->iov_len > UV__IO_MAX_BYTES ? UV__IO_MAX_BYTES : bufs->iov_len);
    } else if (nbufs > 1) {
      r = readv(fd, bufs, nbufs);
    }
  } else {
    if (nbufs == 1) {
      r = pread(fd, bufs->iov_base,
                bufs->iov_len > UV__IO_MAX_BYTES ? UV__IO_MAX_BYTES : bufs->iov_len,
                off);
    }
    else if (nbufs > 1) {
      r = uv__preadv(fd, bufs, nbufs, off);
    }
  }

#ifdef __PASE__
  /* PASE returns EOPNOTSUPP when reading a directory, convert to EISDIR */
  if (r == -1 && errno == EOPNOTSUPP) {
    struct stat buf;
    ssize_t rc;
    rc = uv__fstat(fd, &buf);
    if (rc == 0 && S_ISDIR(buf.st_mode)) {
      errno = EISDIR;
    }
  }
#endif

  /* We don't own the buffer list in the synchronous case. */
  if (req->cb != NULL)
    if (req->bufs != req->bufsml)
      uv__free(req->bufs);

  req->bufs = NULL;
  req->nbufs = 0;

  return r;
}
