```typescript
/** Decides whether a request may proceed, following Go's `net/http.CrossOriginProtection.Check`: 1. `GET`, `HEAD` and `OPTIONS` are always allowed (they must not change    state). Methods are compared case-sensitively, as HTTP defines them. 2. When `Sec-Fetch-Site` is present, `same-origin` and `none` (a    user-initiated navigation such as a bookmark) are allowed. Any other    value (`same-site`, `cross-site`, or anything unexpected) is rejected    unless the request is exempt. 3. Without `Sec-Fetch-Site`, a request without `Origin` is allowed: it comes    from a non-browser client, or from a browser that sends neither header    for same-origin requests. 4. Otherwise the host of `Origin` is compared with the request authority,    case-insensitively, and ignoring the default port of the `Origin` scheme    (`https://a.example` matches `a.example:443`). A match is allowed (the    scheme is not known, so an HTTP to HTTPS request fails open, as in Go;    HSTS mitigates that). A mismatch is rejected unless the request is    exempt. A request is exempt when it matches an exclusion or when its `Origin` is one of the trusted origins. */
export function evaluateCrossOriginRequest(
  request: CrossOriginRequestInfo,
  exemptions: CrossOriginExemptions = {},
): CrossOriginDecision {
  if (SAFE_METHODS.has(request.method)) {
    return { allowed: true, reason: 'safe-method' };
  }

  const secFetchSite = request.secFetchSite;
  if (secFetchSite) {
    if (secFetchSite === 'same-origin' || secFetchSite === 'none') {
      return { allowed: true, reason: 'same-origin' };
    }
    return exemptOr(request, exemptions, 'cross-origin-sec-fetch-site');
  }

  const origin = request.origin;
  if (!origin) {
    return { allowed: true, reason: 'no-browser-headers' };
  }
  if (request.host !== undefined && originMatchesHost(origin, request.host)) {
    return { allowed: true, reason: 'origin-matches-host' };
  }
  return exemptOr(request, exemptions, 'cross-origin-origin-header');
}
