            if (os.zip.shouldInclude(zipEntry.getName, excludePatterns, includePatterns)) {
              lastAction = handleItem((zipEntry, zipInputStream))
            }
            zipEntry = zipInputStream.getNextEntry
          }
        } finally {
          zipInputStream.closeEntry()
          zipInputStream.close()
        }
      }
      lastAction
    }
