/** Calculate Jaccard similarity between two titles Returns a value between 0 (no similarity) and 1 (identical) */
export function calculateTitleSimilarity(
  title1: string,
  title2: string,
): number {
  const words1 = new Set(tokenize(title1))
  const words2 = new Set(tokenize(title2))

  if (words1.size === 0 || words2.size === 0) return 0

  const intersection = new Set([...words1].filter((w) => words2.has(w)))
  const union = new Set([...words1, ...words2])

  return intersection.size / union.size
}
