    if (input > profile.MaximumValue || input < profile.MinimumValue)
    {
        throw new ArgumentOutOfRangeException(
            nameof(input),
            input,
            $"The configured profile supports values from {profile.MinimumValue} through {profile.MaximumValue}.");
