  def go(ft: FreeT[S, M, A]): M[Either[FreeT[S, M, A], A]] =
    ft match {
      case Suspend(ma) =>
        M.flatMap(ma) {
          case Right(a) => M.pure(Right(a))
          case Left(sa) => M.map(f(sa))(Right(_))
