      case Suspend(ma) =>
        M.flatMap(ma) {
          case Right(a) => M.pure(Right(a))
          case Left(sa) => M.map(f(sa))(Right(_))
        }
      case g @ FlatMapped(_, _) =>
        g.a match {
          case Suspend(mx) =>
            M.flatMap(mx) {
              case Right(x) => M.pure(Left(g.f(x)))
              case Left(sx) => M.map(f(sx))(x => Left(g.f(x)))
