/** The cookies, as `name -> value` pairs, that should be sent with a request to `uri`, according to domain-matching, path-matching and the `Secure` attribute (secure cookies are only sent over `https`). */
def cookiesFor(uri: Uri): Seq[(String, String)] = {
  val host = hostOf(uri)
  val path = pathOf(uri)
  val secure = uri.scheme.exists(_.equalsIgnoreCase("https"))
  entries.collect { case (key, stored) if matches(key, stored, host, path, secure) => key.name -> stored.value }.toSeq
}
