def maximumNel[A](fa: F[A])(implicit A: Order[A]): NonEmptyList[A] =
  reduceLeftTo(fa)(NonEmptyList.one) {
    case (l @ NonEmptyList(b, _), a) if A.compare(a, b) < 0  => l
