    #[group(skip)]
    pub(crate) struct Compose<L: Args, R: Args> {
        #[command(flatten)]
        pub(crate) left: L,
        #[command(flatten)]
        pub(crate) right: R,
    }

    #[derive(clap::Args, Clone, Copy, Debug)]
    #[group(skip)]
