int print_lines(const char* buffer, size_t size, FILE* stream, int partial) {
  const char* start;
  const char* end;

  start = buffer;
  while ((end = memchr(start, '\n', &buffer[size] - start))) {
    if (partial == 0)
      fputs("# ", stream);
    else
      partial = 0;

    fwrite(start, 1, (int)(end - start), stream);
    fputs("\n", stream);
    fflush(stream);
    start = end + 1;
  }

  end = &buffer[size];
  if (start < end) {
    if (partial == 0)
      fputs("# ", stream);

    fwrite(start, 1, (int)(end - start), stream);
    fflush(stream);
    return 1;
  }

  return 0;
}
