def maximumList[A](fa: F[A])(implicit A: Order[A]): List[A] =
  foldLeft(fa, List.empty[A]) {
    case (l @ (b :: _), a) if A.compare(a, b) < 0  => l
    case (l @ (b :: _), a) if A.compare(a, b) == 0 => a :: l
