```typescript
/** A `$ref` on its own describes exactly the component it points at, so compare through the component - otherwise the same shape reached both by reference and inline looks like two distinct schemas. */
function resolveBareRef(
  schema: SchemaObject,
  components: Record<string, SchemaObject>,
): SchemaObject {
  if (!isBareRef(schema)) {
    return schema;
  }
  const target = getReferencedSchema(schema, components);
  // A component mid-conversion is still an empty placeholder (cyclic types);
  // compare those by their `$ref` so distinct ones stay distinct.
  return target && isNonEmptySchema(target) ? target : schema;
}
