                 read_req.result, NULL);
  ASSERT_OK(r);
  ASSERT_OK(read_req.result);
  uv_fs_req_cleanup(&read_req);

  r = uv_fs_close(NULL, &close_req, open_req1.result, NULL);
  ASSERT_OK(r);
  ASSERT_OK(close_req.result);
  uv_fs_req_cleanup(&close_req);

  /* Cleanup */
  unlink("test_file");
}
