        bodyWithoutStackTraces.match(
          new RegExp(
            normalizedKeyword.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'),
            'gi',
          ),
        ) || []
      ).length
      score += bodyMatches * category.weight
    }

    // Check patterns (1.5x weight for title, 1x for body)
    for (const pattern of category.patterns) {
      if (pattern.test(title)) {
