```javascript
/** Canonicalize an IPv4 address written in shorthand, octal, or hex form into dotted-decimal. IPv6 addresses and non-IP strings are returned unchanged so the existing IPv4-mapped IPv6 unmap path and the isLoopback path can still see them. Shorthand expansion mirrors Node's URL parser: literal parts fill from the left, the final part fills the remaining octets from the right with zero-padding on the left.   127.1     -> 127.0.0.1   127.0.1   -> 127.0.0.1   1.2.3     -> 1.2.0.3 Each octet is parsed with an explicit base: 16 for `0x`/`0X` prefix, 8 for zero-prefixed multi-digit all-`0-7` parts, 10 otherwise. Zero-prefixed decimal-looking parts that contain `8` or `9` are rejected to match Node's URL parser, and the comparison layer falls through to non-bypass if either side rejects the form (fail-safe). Returns the input unchanged on any parse failure, out-of-range octet, or unusual shape (1-part, 5+ parts) so the comparison layer fails closed. */
const parseIPv4Octet = (text) => {
  if (/^0[xX][0-9a-fA-F]+$/.test(text)) {
    const n = parseInt(text.slice(2), 16);
    return Number.isFinite(n) ? n : null;
  }
  if (text.length > 1 && /^0[0-7]+$/.test(text)) {
    const n = parseInt(text, 8);
    return Number.isFinite(n) ? n : null;
  }
  if (text.length > 1 && /^0[0-9]+$/.test(text)) {
    return null;
  }
  if (/^[0-9]+$/.test(text)) {
    const n = parseInt(text, 10);
    return Number.isFinite(n) ? n : null;
  }
  return null;
}
