/**
 * VirtualColumn decorator is used to mark a specific class property as a Virtual column.
 *
 * @param typeOrOptions
 * @param options
 */
export function VirtualColumn(
    typeOrOptions: ColumnType,
    options: VirtualColumnOptions,
