/** Finds the uppermost expression node that can evaluate to the given one. Examples:    If given `a` in `a || foo`, it returns the `a || foo` node.    If given `a` in `foo ? a : bar`, it returns the `foo ? a : bar` node.    If given `a` in `foo ? bar : (baz && a)`, it returns the `foo ? bar : (baz && a)` node.    If given `a` in `a ? foo : bar`, it returns the `a` node.    If given `a` in `foo(a)`, it returns the `a` node. */
function unwrapExpression(expression) {
			const { parent } = expression;

			const shouldUnwrap =
				parent.type === "LogicalExpression" ||
				(parent.type === "ConditionalExpression" &&
					parent.test !== expression);

