        {
            switch (step)
            {
                case Fold<A, Unit>.Done(_):
                    yield break;

                case Fold<A, Unit>.Loop(_, var value, var next):
                    yield return value;
                    step = next(default);
                    break;

                default:
                    throw new NotSupportedException();
            }
        }
    }
}
