/** Attempts to load and cache a package. Returns the loaded module on success or `null` if the package is not installed. Unlike {@link loadPackage}, this function does **not** terminate the process when the package is missing, making it suitable for optional dependencies. */
export async function tryLoadPackage(
  packageName: string,
  loaderFn?: Function,
): Promise<any> {
  const cached = packageCache.get(packageName);
  if (cached) {
    return cached;
  }
  try {
    const pkg = loaderFn ? await loaderFn() : await import(packageName);
    packageCache.set(packageName, pkg);
    return pkg;
  } catch {
    return null;
  }
}
