        else if (value <= -11)
        {
            value = -(value + 11);
            write_bon8_bytes(0xC2 + ((value >> 6) & 0x1F), 0xC0 + (value & 0x3F));
        }
        else if (value <= -1)
        {
            write_bon8_bytes(0xB8 - (value + 1));
