    self.whenAAAALookupComplete(future: aaaaLookup)

    let aLookup = self.connector.resolver.initiateAQuery(
        host: self.connector.host,
        port: self.connector.port
    ).hop(to: self.connector.loop).assumeIsolatedUnsafeUnchecked()
