/** Gets the value of the given node if it's a static value other than a regular expression object, or the node's `regex` property. The purpose of this method is to provide a replacement for `getStaticValue` in environments where certain regular expressions cannot be evaluated. A known example is Node.js 18 which does not support the `v` flag. Calling `getStaticValue` on a regular expression node with the `v` flag on Node.js 18 always returns `null`. A limitation of this method is that it can only detect a regular expression if the specified node is itself a regular expression literal node. */
function getStaticValueOrRegex(node, initialScope) {
	if (!node) {
		return null;
	}
	if (node.type === "Literal" && node.regex) {
		return { regex: node.regex };
	}

	const staticValue = getStaticValue(node, initialScope);

	if (staticValue?.value instanceof RegExp) {
		return null;
	}
	return staticValue;
}
