```typescript
/** Finds re-exports from a module (`export { X } from "module"`) and renames specifiers according to the `renames` map. Also matches sub-path re-exports (`export { X } from "module/sub/path"`). When the re-export has an alias (`export { X as Y }`), only the local name is renamed so downstream consumers continue to see the same exported name. Returns true if any specifiers were renamed. */
export const renameReExportSpecifiers = (
    root: Collection,
    j: JSCodeshift,
    moduleName: string,
    renames: Record<string, string>,
): boolean => {
    let renamed = false

    root.find(j.ExportNamedDeclaration).forEach((exportPath) => {
        const source = exportPath.node.source?.value
        if (!matchesModuleOrSubPath(source, moduleName)) return

        exportPath.node.specifiers?.forEach((spec) => {
            if (
                spec.type !== "ExportSpecifier" ||
                spec.local?.type !== "Identifier"
            ) {
                return
            }
            const newName = renames[spec.local.name]
            if (!newName) return

            const wasAlias =
                spec.exported.type === "Identifier" &&
                spec.exported.name !== spec.local.name

            spec.local.name = newName
            if (!wasAlias && spec.exported.type === "Identifier") {
                spec.exported.name = newName
            }
            renamed = true
        })
    })

    return renamed
}
