```swift
/// When the current `EventLoopFuture<Value>` is in an error state, run the provided callback, which may recover from the error by returning an `EventLoopFuture<NewValue>`. The callback is intended to potentially recover from the error by returning a new `EventLoopFuture` that will eventually contain the recovered result.
public func flatMapError(
    _ callback: @escaping @Sendable (Error) -> EventLoopFuture<Value>
) -> EventLoopFuture<Value> where Value: Sendable {
    let next = EventLoopPromise<Value>.makeUnleakablePromise(eventLoop: self.eventLoop)
    self._whenComplete {
        switch self._value! {
        case .success(let t):
            return next._setValue(value: .success(t))
        case .failure(let e):
            let t = callback(e)
            if t.eventLoop.inEventLoop {
                return t._addCallback {
                    next._setValue(value: t._value!)
                }
            } else {
                t.cascade(to: next)
                return CallbackList()
            }
        }
    }
    return next.futureResult
}
