public func withBoundSocket(_ socket: NIOBSDSocket.Handle) -> EventLoopFuture<Channel> {
    func makeChannel(
        _ eventLoop: SelectableEventLoop,
        _ childEventLoopGroup: EventLoopGroup,
        _ enableMPTCP: Bool
    ) throws -> ServerSocketChannel {
