        gson.fromJson(
            "{\"userS\":null,\"userSN\":null,\"userD\":null,\"userDN\":null}", WithNullSafe.class);
    // For @JsonAdapter with serializer nullSafe is ignored when deserializing
    assertThat(deserialized.userS.name).isEqualTo("fallback-read");
