```scala
/** Remove duplicates by a predicate. Duplicates are checked using `Order[_]` instance. Example: {{{ scala> import cats.data.Chain scala> val chain = Chain(1, 2, 3, 4) scala> chain.distinctBy(_ / 2) res0: cats.data.Chain[Int] = Chain(1, 2, 4) }}} */
def distinctBy[B](f: A => B)(implicit O: Order[B]): Chain[A] = {
  if (isEmptyOrSingleton) this
  else {
    implicit val ord: Ordering[B] = O.toOrdering

    val bldr = Vector.newBuilder[A]
    val seen = mutable.TreeSet.empty[B]
    val it = iterator
    while (it.hasNext) {
      val next = it.next()
      if (seen.add(f(next)))
        bldr += next
    }
    // Result can contain a single element only.
    Chain.fromSeq(bldr.result())
  }
}
