    static std::size_t calc_bson_binary_size(const BasicJsonType& j)
    {
        const auto& value = *j.m_data.m_value.binary;

        if (value.has_subtype() && JSON_HEDLEY_UNLIKELY(value.subtype() > (std::numeric_limits<std::uint8_t>::max)()))
