  // No hoisting needed
  if (!context.hoistStatic) {
    return finalExp
  }

  // Check for existing hoisted expression
  const existingHoistIndex = context.hoists.findIndex(h => {
    return (
      h &&
      h.type === NodeTypes.SIMPLE_EXPRESSION &&
      !h.isStatic &&
      h.content === hashExp
