    var sameMonth = comparisonBase.Date.AddMonths(tense == Tense.Future ? 1 : -1) == input.Date;

    var days = Math.Abs((input.Date - comparisonBase.Date).Days);

    return DefaultHumanize(ts, sameMonth, days, tense, culture);
}
