                return _setattr(attr_name, value_var, has_on_setattr)
            return f"_inst_dict['{attr_name}'] = {value_var}"

        def fmt_setter_with_converter(attr_name: str, value_var: str, has_on_setattr: bool, converter: Converter) -> str:
            if has_on_setattr or _is_slot_attr(attr_name, base_attr_map):
                return _setattr_with_converter(attr_name, value_var, has_on_setattr, converter)
            return f"_inst_dict['{attr_name}'] = {converter._fmt_converter_call(attr_name, value_var)}"
        return (('_inst_dict = self.__dict__',), fmt_setter, fmt_setter_with_converter)
    return ((), _assign, _assign_with_converter)
