        return Unicode.Scalar(scalar).map { String($0) }

    case 0xF0...0xF4:
        // Lead of 4-byte seq.
        //   0xF0 → U+10000 (minimum to avoid overlong)
        //   0xF1…0xF3 → (byte & 0x07) << 18
        //   0xF4 → must be ≤ U+10FFFF
        let scalar: UInt32
