```javascript
/** private _uniqContentEquals function. That function is checking equality of 2 iterator contents as multisets, assuming the two iterators have the same length (guaranteed by the caller). Members are matched greedily: each element of *a* consumes the first not-yet-consumed value-equal element of *b*. This is symmetric and handles value-equal but reference-distinct members with correct multiplicity, e.g. - `new Set([{v: 1}, {v: 1}])` vs `new Set([{v: 1}, {v: 2}])` (unequal) - `[{v: 1}, {v: 1}, {v: 2}]` vs `[{v: 1}, {v: 2}, {v: 2}]` (unequal) */
function _uniqContentEquals(aIterator, bIterator, stackA, stackB) {
  var a = _arrayFromIterator(aIterator);
  var b = _arrayFromIterator(bIterator);

  function eq(_a, _b) {
    return _equals(_a, _b, stackA.slice(), stackB.slice());
  }

  if (a.length !== b.length) {
    return false;
  }

  var consumed = [];
  var idx = 0;
  while (idx < a.length) {
    var found = false;
    var jdx = 0;
    while (jdx < b.length) {
      if (!consumed[jdx] && eq(a[idx], b[jdx])) {
        consumed[jdx] = true;
        found = true;
        break;
      }
      jdx += 1;
    }
    if (!found) {
      return false;
    }
    idx += 1;
  }
  return true;
}
