def cataM[F[_], M[_], A, B](
  cof: Cofree[F, A]
)(folder: (A, F[B]) => M[B])(inclusion: Eval ~> M)(implicit F: Traverse[F], M: Monad[M]): M[B] = {
  def loop(fr: Cofree[F, A]): Eval[M[B]] = {
