        std::size_t length = 0;
        while (length < remaining && data[length] != 0x00)
        {
            ++length;
        }
        if (length == remaining)
        {
            return false;
        }
        result.append(reinterpret_cast<const typename string_t::value_type*>(data), length);
        // consume the string and its \x00-byte, as the byte-wise path does
        ia.bulk_skip(length + 1);
        chars_read += length + 1;
        current = 0x00;
        return true;
    }
