    if (!e || e.reset <= now) { hits.set(key, { count: 1, reset: now + cfg.windowMs }); return 0; }
    e.count++;
    return e.count > cfg.max ? Math.max(1, Math.ceil((e.reset - now) / 1000)) : 0;
  };
