public static virtual Seq<A> ToSeq<A>(K<T, A> ta)
{
    return new Seq<A>(go());

    IEnumerable<A> go()
    {
        var step = T.FoldStep(ta, unit);
        while (true)
        {
            switch (step)
            {
                case Fold<A, Unit>.Done(_):
                    yield break;

                case Fold<A, Unit>.Loop(_, var value, var next):
