def test_option_name_case_variants_share_one_parameter(runner):
    """Case variants of one option collapse onto a single parameter."""

    @click.command()
    @click.option("--foo-bar")
    @click.option("--Foo-Bar")
    @click.option("--FOO-BAR")
    def cmd(**kwargs):
        click.echo(repr(kwargs))

