    assert not [w for w in caught if issubclass(w.category, UserWarning)]
    for spelling in ("--foo-bar", "--Foo-Bar", "--FOO-BAR"):
        assert spelling in result.output

    for spelling, value in (("--foo-bar", "a"), ("--Foo-Bar", "b"), ("--FOO-BAR", "c")):
