function removeStackTraces(text: string): string {
  return text
    .split('\n')
    .filter((line) => {
      const trimmed = line.trim()
      // Skip lines starting with "at " (stack traces)
      if (trimmed.startsWith('at ')) return false
      // Skip lines with file paths (e.g., "node_modules/", "src/", ".js:", ".ts:")
