/** Synchronously loads a package using `createRequire` and caches it. This is meant for optional dependencies that must be loaded in synchronous contexts (e.g. constructors). */
export function loadPackageSync(
  packageName: string,
  context: string,
  loaderFn?: () => any,
): any {
  const cached = packageCache.get(packageName);
  if (cached) {
    return cached;
  }
  try {
    const pkg = loaderFn
      ? loaderFn()
      : createRequire(import.meta.url)(packageName);
    packageCache.set(packageName, pkg);
    return pkg;
  } catch (e) {
    logger.error(MISSING_REQUIRED_DEPENDENCY(packageName, context));
    Logger.flush();
    process.exit(1);
  }
}
