/// Returns a `Result` representing the value returned from the given closure or an `Errno` if that value was -1.
public func valueOrErrno<I: FixedWidthInteger>(
    retryOnInterrupt: Bool = true,
    _ fn: () -> I
) -> Result<I, Errno> {
    while true {
