/** Fetch the start and end of DST for the local time zone in a given year. We'll assume that DST start & end are the first forward and the last back transitions in the year, except transitions in Jan or Dec which are likely to be permanent TZ changes rather than DST changes. */
export function getDstTransitions(year: number): PartialInterval {
  const result: PartialInterval = {
    start: undefined,
    end: undefined,
  };
  const transitions = getTzOffsetTransitions(year);
  for (let i = 0; i < transitions.length; i++) {
    const t = transitions[i];
    const month = t.date.getMonth();
    if (month > 0 && month < 11) {
      if (t.type === "forward") result.start = t.date;
      if (t.type === "back" && !result.end) result.end = t.date;
    }
  }
  return result;
}
