      assertThat(cal.get(Calendar.HOUR_OF_DAY)).isEqualTo(14);
      assertThat(cal.get(Calendar.MINUTE)).isEqualTo(29);
      assertThat(cal.get(Calendar.SECOND)).isEqualTo(23);
