{
    var magnitude = GetAbsoluteValue(input);
    if (magnitude == 0)
    {
        return profile.ZeroWord;
    }

    var parts = new List<string>();
    foreach (var scale in profile.Scales)
    {
        var count = (int)(magnitude / scale.Value);
        if (count == 0)
        {
            continue;
