```typescript
/** Issues a GET request and closes the client connection after `killAfterMs`, simulating a client that goes away while the server is still producing. */
export function requestAndAbort(
  port: number,
  path: string,
  killAfterMs: number,
): Promise<void> {
  return new Promise<void>((resolve, reject) => {
    const req = http.get({ host: '127.0.0.1', port, path }, res => {
      res.on('data', () => undefined);
      res.on('error', () => undefined);
    });
    req.on('error', err => {
      if ((err as NodeJS.ErrnoException).code !== 'ECONNRESET') {
        reject(err);
      }
    });
    setTimeout(() => {
      req.destroy();
      resolve();
    }, killAfterMs);
  });
}
```

