/** `usePrefetchInfiniteQuery` does not return anything — it fires a prefetch as a reactive side effect, useful for kicking off a fetch ahead of the component that will actually render the data with `useInfiniteQuery`. You can pass everything to `usePrefetchInfiniteQuery` that you can pass to `queryClient.infiniteQuery`, though `queryKey`, `initialPageParam`, and `getNextPageParam` are always required, and `queryFn` is required unless a default query function has been defined. `getNextPageParam` receives both the last page of the infinite list of data and the full array of all pages, as well as pageParam information, and should return a single variable that will be passed to your query function as `context.pageParam`. Return `undefined` or `null` to indicate there is no next page available. The prefetch is skipped if the query already has any cached state — including a `pending`/`error` state left over from a previous attempt — so it won't refetch data that's already there or already in flight. It re-runs whenever a reactive dependency in `options` (built with `infiniteQueryOptions`, for example) changes. Fire this during render, before a suspense boundary that wraps a component using `useInfiniteQuery`'s `suspense()` — see the {@link https://tanstack.com/query/latest/docs/framework/vue/guides/suspense | Suspense guide}. */
export function usePrefetchInfiniteQuery<
  TQueryFnData = unknown,
  TError = DefaultError,
  TData = InfiniteData<TQueryFnData>,
  TQueryKey extends QueryKey = QueryKey,
  TPageParam = unknown,
>(
  options: MaybeRefOrGetter<
    MaybeRefDeep<
      UsePrefetchInfiniteQueryOptions<
        TQueryFnData,
        TError,
        TData,
        TQueryKey,
        TPageParam
      >
    >
  >,
  queryClient?: QueryClient,
): void {
  if (process.env.NODE_ENV === 'development') {
    if (!getCurrentScope()) {
      console.warn(
        'vue-query composable like "useQuery()" should only be used inside a "setup()" function or a running effect scope. They might otherwise lead to memory leaks.',
      )
    }
  }

  const client = queryClient || useQueryClient()

  watchEffect(() => {
    const resolvedOptions = isGetter(options) ? options() : unref(options)

    const clonedOptions: UsePrefetchInfiniteQueryOptions<
      TQueryFnData,
      TError,
      TData,
      TQueryKey,
      TPageParam
    > = cloneDeepUnref(resolvedOptions)

    if (!client.getQueryState(clonedOptions.queryKey)) {
      void client.infiniteQuery(clonedOptions).then(noop).catch(noop)
