        g1.a match {
          case Suspend(m1) =>
            M.map(m1) {
              case Right(a) => Left(g1.f(a))
              case Left(fc) => Right(Left(S.map(fc)(g1.f(_))))
            }
          case g2 @ FlatMapped(_, _) => M.pure(Left(g2.a.flatMap(g2.f(_).flatMap(g1.f))))
        }
    }

  M.tailRecM(this)(go)
}
