          List(Term.ApplyInfix.Initial(actual, Term.Name(op), List(), List(expected)))
        ) if op == "==" || op == "===" =>
      Patch.replaceTree(t, s"$actual ?= $expected")
    case t @ Term.Apply.Initial(Term.Name("assertEquals"), List(actual, expected)) =>
      Patch.replaceTree(t, s"$actual ?= $expected")
    case _ =>
      Patch.empty
