static void on_connection(uv_stream_t* server, int status) {
  uv_tcp_t* conn;
  int r;

  if (!local_conn_accepted) {
    /* Accept the connection and close it.  Also and close the server. */
    ASSERT_OK(status);
    ASSERT_PTR_EQ(&tcp_server, server);

    conn = malloc(sizeof(*conn));
