```typescript
/** Finds re-exports from a module (`export { X } from "module"`) and removes the named specifiers listed in `specifierNames`. Also matches sub-path re-exports (`export { X } from "module/sub/path"`). Removes the entire `ExportNamedDeclaration` if no specifiers remain. Returns true if any specifiers were removed. */
export const removeReExportSpecifiers = (
    root: Collection,
    j: JSCodeshift,
    moduleName: string,
    specifierNames: Set<string>,
): boolean => {
    let removed = false

    root.find(j.ExportNamedDeclaration).forEach((exportPath) => {
        const source = exportPath.node.source?.value
        if (!matchesModuleOrSubPath(source, moduleName)) return

        const remaining = exportPath.node.specifiers?.filter((spec) => {
            if (
                spec.type === "ExportSpecifier" &&
                spec.local?.type === "Identifier" &&
                specifierNames.has(spec.local.name)
            ) {
                removed = true
                return false
            }
            return true
        })

        if (remaining?.length === 0) {
            j(exportPath).remove()
        } else if (remaining) {
            exportPath.node.specifiers = remaining
        }
    })

    return removed
}
